-- 2026-10-31q: MP Background timelines for batch 15, 25 more current MPs (owner's approval, "yes", 31 Oct 2026).
-- Sets background_timeline (314 entries, copied exactly from "background-batch15.json", which is not committed) and
-- background_last_checked = 2026-10-31 for member_ids 4316, 4357, 4358, 4362, 4366, 4368, 4382, 4384, 4391, 4394, 4396, 4397, 4407, 4409, 4418, 4444, 4449, 4456, 4460, 4479, 4480, 4493, 4500, 4501, 4505,
-- each only WHERE background_timeline IS NULL. Every array passed lib/background-timeline.ts validate(). Every source link was checked by Cowork
-- before the data file was written.
-- Nothing else changes. No code change. Backup of the 25 rows, off the repo: "Claude outputs/backups/2026-10-31q-mp-biography-before.csv".
-- Guards (RAISE): exactly 25 rows change, all of them these 25; the 296 existing timelines are unchanged (md5);
-- MPs with a timeline go from 296 to 321; each array equals the file exactly; 4492 entries in all afterwards.
-- Undo: 2026-10-31q-UNDO.sql.
\set ON_ERROR_STOP on
BEGIN;
SET LOCAL statement_timeout = '60s';
SET LOCAL lock_timeout = '5s';

DO $$ BEGIN
  IF (SELECT count(*) FROM public.mp_biography WHERE member_id IN (4316, 4357, 4358, 4362, 4366, 4368, 4382, 4384, 4391, 4394, 4396, 4397, 4407, 4409, 4418, 4444, 4449, 4456, 4460, 4479, 4480, 4493, 4500, 4501, 4505)) <> 25 THEN RAISE EXCEPTION 'expected 25 biography rows'; END IF;
  IF EXISTS (SELECT 1 FROM public.mp_biography WHERE member_id IN (4316, 4357, 4358, 4362, 4366, 4368, 4382, 4384, 4391, 4394, 4396, 4397, 4407, 4409, 4418, 4444, 4449, 4456, 4460, 4479, 4480, 4493, 4500, 4501, 4505) AND background_timeline IS NOT NULL) THEN RAISE EXCEPTION 'a new MP already has a timeline'; END IF;
  IF (SELECT count(*) FROM public.mp_biography WHERE background_timeline IS NOT NULL) <> 296 THEN RAISE EXCEPTION 'expected 296 MPs with a timeline before'; END IF;
END $$;

CREATE TEMP TABLE bt_before ON COMMIT DROP AS
SELECT member_id, md5(to_jsonb(b)::text) AS h, md5(coalesce(background_timeline::text, '')) AS th, (background_timeline IS NOT NULL) AS had
  FROM public.mp_biography b;

CREATE TEMP TABLE bt_new (member_id integer PRIMARY KEY, n integer NOT NULL, tl jsonb NOT NULL) ON COMMIT DROP;
